    #[test]
    fn test_create_sheet_rejects_folder_under_system_project() {
        let app = setup();
        let db_state = app.state::<DbState>();
        {
            let conn = db_state.0.lock().unwrap();
            seed_project(&conn, "proj-a", "ProjectA", false);
            seed_project(&conn, "sys-proj", "System", true);
            seed_folder(&conn, "folder-1", "Folder", "sys-proj", false);
        }
        // #2874 item 50b (ruling 10) changed this test's expected outcome: before
        // 50b, the AI handler's unscoped folder lookup would resolve "folder-1" by
        // ID alone (ignoring that its real parent is "sys-proj", not the declared
        // "proj-a"), and only notes.rs's deeper is_system-ancestor guard caught it,
        // with the "system folder" message. Branch A (resolve_folder_branch_a) now
        // scopes the ID lookup to the DECLARED project_id — folder-1 does not
        // belong to proj-a at all, so this is refused earlier, as a plain
        // not-found-in-this-project error, and notes.rs's deeper guard is never
        // reached. This is ruling 10 working as intended: a folder ID belonging to
        // a different project is refused outright, never silently remapped.
        let params = serde_json::json!({ "title": "Nope", "project_id": "proj-a", "folder_id": "folder-1" });
        let result = execute_create_sheet(&params, &db_state);
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(
            err.contains("not found in this project"),
            "a folder_id belonging to a different project must be refused as not-found-in-this-project (ruling 10), got: {}",
            err
        );
    }

