        // Set, then clear.
        let set_params = serde_json::json!({ "note_id": note_id, "cells": [{ "row_id": row_id, "column_id": col_id, "value": "Temp" }] });
        execute_set_sheet_cells(&set_params, &db_state).unwrap();
