    // Item 37: cross-sheet leakage guard.
    #[test]
    fn test_batch_cell_row_id_belongs_to_different_sheet_rejected() {
        let app = setup();
        let db_state = app.state::<DbState>();
        {
            let conn = db_state.0.lock().unwrap();
            seed_project(&conn, "proj-a", "ProjectA", false);
        }
        let note_id_a = create_sheet_for_test(&db_state, "proj-a", "Sheet A");
        let note_id_b = create_sheet_for_test(&db_state, "proj-a", "Sheet B");

        // Row belongs to sheet B.
        let row_result = execute_add_sheet_row(&serde_json::json!({ "note_id": note_id_b }), &db_state).unwrap();
        let row_id_b = serde_json::from_str::<serde_json::Value>(&row_result).unwrap()["row_id"].as_str().unwrap().to_string();

        let data_a = get_sheet_data_value(&db_state, &note_id_a);
        let col_id_a = data_a["columns"][0]["id"].as_str().unwrap().to_string();

        // Tool call claims note_id_a but supplies sheet B's row_id.
        let cells = serde_json::json!([{ "row_id": row_id_b, "column_id": col_id_a, "value": "Leak" }]);
        let params = serde_json::json!({ "note_id": note_id_a, "cells": cells });
        let result = execute_set_sheet_cells(&params, &db_state).unwrap();
        let parsed: serde_json::Value = serde_json::from_str(&result).unwrap();
        assert_eq!(parsed["written"], 0, "cross-sheet write must be rejected, not silently applied");
        assert_eq!(parsed["errors"].as_array().unwrap().len(), 1);

        // Confirm sheet B's row was NOT written either (defensive check).
        let data_b = get_sheet_data_value(&db_state, &note_id_b);
        assert_eq!(data_b["cells"].as_array().unwrap().len(), 0);
    }

    // Item 38: snapshot-count / throttle assertion — a 10-cell batch produces
    // exactly ONE new snapshot (maybe_capture_sheet_snapshot's throttle, not
    // bypassed, applies per-cell inside update_sheet_cell_internal).
    #[test]
    fn test_batch_ten_cell_write_produces_exactly_one_new_snapshot() {
        let app = setup();
        let db_state = app.state::<DbState>();
        {
            let conn = db_state.0.lock().unwrap();
            seed_project(&conn, "proj-a", "ProjectA", false);
        }
        let note_id = create_sheet_for_test(&db_state, "proj-a", "Snapshot Sheet");

        // 10 rows, one column each written to keep it simple: reuse column 1
        // across 10 different rows so there are 10 distinct cells to write.
        let mut row_ids = Vec::new();
        for _ in 0..10 {
            let row_result = execute_add_sheet_row(&serde_json::json!({ "note_id": note_id }), &db_state).unwrap();
            let row_id = serde_json::from_str::<serde_json::Value>(&row_result).unwrap()["row_id"].as_str().unwrap().to_string();
            row_ids.push(row_id);
        }
        let data = get_sheet_data_value(&db_state, &note_id);
        let col_id = data["columns"][0]["id"].as_str().unwrap().to_string();

        // Backdate every existing snapshot for this note past the throttle
        // window (mirrors `sheets_snapshots.rs`'s own
        // `backdate_all_sheet_snapshots` test helper) — the 10 preceding
        // `create_sheet_row_internal` calls each bypass the throttle
        // (structural mutation, `maybe_capture_sheet_snapshot(.., true)`) and
        // so already left a very-recent snapshot behind; without backdating,
        // the first cell write's OWN (non-bypassed) capture attempt would
        // itself be throttled by that recent row-insert snapshot, and the
        // count-of-new-snapshots this test is asserting on would be 0, not 1
        // — masking the very throttle behavior under test.
        {
            let conn = db_state.0.lock().unwrap();
            let ts = (chrono::Utc::now() - chrono::Duration::seconds(61)).to_rfc3339();
            conn.execute(
                "UPDATE note_versions SET created_at = ?1 WHERE note_id = ?2 AND source = 'sheet_snapshot'",
                rusqlite::params![ts, note_id],
            )
            .unwrap();
        }

        let snapshot_count_before: i64 = {
            let conn = db_state.0.lock().unwrap();
            conn.query_row(
                "SELECT COUNT(*) FROM note_versions WHERE note_id = ?1 AND source = 'sheet_snapshot'",
                rusqlite::params![note_id],
                |r| r.get(0),
            )
            .unwrap()
        };

        let cells: Vec<serde_json::Value> = row_ids
            .iter()
            .map(|rid| serde_json::json!({ "row_id": rid, "column_id": col_id, "value": "X" }))
            .collect();
        let params = serde_json::json!({ "note_id": note_id, "cells": cells });
        let result = execute_set_sheet_cells(&params, &db_state).unwrap();
        let parsed: serde_json::Value = serde_json::from_str(&result).unwrap();
        assert_eq!(parsed["written"], 10, "all 10 cells must write successfully");

        let snapshot_count_after: i64 = {
            let conn = db_state.0.lock().unwrap();
            conn.query_row(
                "SELECT COUNT(*) FROM note_versions WHERE note_id = ?1 AND source = 'sheet_snapshot'",
                rusqlite::params![note_id],
                |r| r.get(0),
            )
            .unwrap()
        };

        assert_eq!(
            snapshot_count_after - snapshot_count_before,
            1,
            "a burst of 10 cell edits in one batch must produce exactly ONE new snapshot (throttle), not ten"
        );
    }

