    #[test]
    fn test_delete_sheet_column_happy_path_removes_column_and_cells() {
        let app = setup();
        let db_state = app.state::<DbState>();
        {
            let conn = db_state.0.lock().unwrap();
            seed_project(&conn, "proj-a", "ProjectA", false);
        }
        let note_id = create_sheet_for_test(&db_state, "proj-a", "Delete Col Sheet");
        let row_result = execute_add_sheet_row(&serde_json::json!({ "note_id": note_id }), &db_state).unwrap();
        let row_id = serde_json::from_str::<serde_json::Value>(&row_result).unwrap()["row_id"].as_str().unwrap().to_string();
        let data = get_sheet_data_value(&db_state, &note_id);
        let target_col_id = data["columns"][0]["id"].as_str().unwrap().to_string();

        let set_params = serde_json::json!({ "note_id": note_id, "cells": [{ "row_id": row_id, "column_id": target_col_id, "value": "Gone" }] });
        execute_set_sheet_cells(&set_params, &db_state).unwrap();

        let del_params = serde_json::json!({ "note_id": note_id, "column_id": target_col_id });
        let del_result = execute_delete_sheet_column(&del_params, &db_state).expect("delete should succeed");
        let del_parsed: serde_json::Value = serde_json::from_str(&del_result).unwrap();
        assert_eq!(del_parsed["note_id"], note_id);
        assert_eq!(del_parsed["column_id"], target_col_id);
        assert_eq!(del_parsed["deleted"], true);

        let data = get_sheet_data_value(&db_state, &note_id);
        assert_eq!(data["columns"].as_array().unwrap().len(), 4, "one column must be removed");
        assert!(
            !data["columns"].as_array().unwrap().iter().any(|c| c["id"] == target_col_id),
            "the deleted column's id must be absent"
        );
        assert!(
            !data["cells"].as_array().unwrap().iter().any(|c| c["column_id"] == target_col_id),
            "no cell with the deleted column_id must remain"
        );
    }

