        // Direct create_sheet_internal call, columns=None (mirrors the Tauri
        // UI command's call site, sheets.rs `create_sheet`).
        let conn = db_state.0.lock().unwrap();
        let request = crate::notes::CreateSheetNoteRequest {
            project_id: "proj-a".to_string(),
            folder_id: None,
            title: "Direct None Sheet".to_string(),
            tags: None,
            status: Some("cabinet".to_string()),
            priority: None,
            due_date: None,
        };
        let data = crate::sheets::create_sheet_internal(&conn, request, None).expect("create_sheet_internal(.., None) should succeed");
        assert_eq!(data.columns.len(), 5, "columns=None must seed 5 default columns");
