    // ── add_sheet_rows / add_sheet_columns (#2970) ────────────────────

    // #2874 item 61: compact format — `columns` given once, each row a
    // positional array (`row[i]` → `columns[i]`). Rewritten from #2970's
    // original `rows: [{values:{...}}]` shape per Matt's replace-outright
    // ruling (1.0.59 unreleased, no back-compat).
    #[test]
    fn test_add_sheet_rows_happy_path_creates_rows_with_values_in_order() {
        let app = setup();
        let db_state = app.state::<DbState>();
        {
            let conn = db_state.0.lock().unwrap();
            seed_project(&conn, "proj-a", "ProjectA", false);
        }
        let note_id = create_sheet_for_test(&db_state, "proj-a", "Rows Sheet");
        let data = get_sheet_data_value(&db_state, &note_id);
        let col_id = data["columns"][0]["id"].as_str().unwrap().to_string();

        let params = serde_json::json!({
            "note_id": note_id,
            "columns": [col_id],
            "rows": [
                ["r0"],
                [serde_json::Value::Null],
                ["r2"],
            ]
        });
        let result = execute_add_sheet_rows(&params, &db_state).expect("add_sheet_rows should succeed");
        let parsed: serde_json::Value = serde_json::from_str(&result).unwrap();
        let row_ids = parsed["row_ids"].as_array().unwrap();
        assert_eq!(row_ids.len(), 3, "must create exactly 3 rows");
        // Every row has a positional entry for every column now (there is no
        // "omit a middle column" option) — `written_cells` counts every
        // upsert attempt, including the null row's blank write, same as the
        // old format's explicit (not omitted) null already did.
        assert_eq!(parsed["written_cells"], 3, "every row writes its one column, including the null row's blank attempt");

        let after = get_sheet_data_value(&db_state, &note_id);
        let rows = after["rows"].as_array().unwrap();
        assert_eq!(rows.len(), 3);
        let cells = after["cells"].as_array().unwrap();
        assert_eq!(cells.len(), 2, "only the 2 non-null rows should have a materialized sheet_cells row (null stays sparse)");
    }

