        let col_id_b = data["columns"][1]["id"].as_str().unwrap().to_string();

        let params = serde_json::json!({
            "note_id": note_id,
            "columns": [col_id_a, col_id_b],
            "rows": [["x"]]
        });
        let result = execute_add_sheet_rows(&params, &db_state);
        let err = result.expect_err("a row shorter than columns must be rejected before any row is created");
        assert!(err.contains("row 0"), "error must name the row index: {}", err);
        assert!(err.contains("expected 2"), "error must name the expected length (2): {}", err);
