    #[test]
    fn test_set_sheet_cells_decimal_value_round_trips_without_float_artifact() {
        let app = setup();
        let db_state = app.state::<DbState>();
        { let conn = db_state.0.lock().unwrap(); seed_project(&conn, "proj-a", "ProjectA", false); }
        let note_id = create_sheet_for_test(&db_state, "proj-a", "Coerce Sheet");
        let col_id = add_number_column(&db_state, &note_id, "Amount");
        let row_result = execute_add_sheet_row(&serde_json::json!({ "note_id": note_id }), &db_state).unwrap();
        let row_id = serde_json::from_str::<serde_json::Value>(&row_result).unwrap()["row_id"].as_str().unwrap().to_string();

        let params = serde_json::json!({ "note_id": note_id, "cells": [{ "row_id": row_id, "column_id": col_id, "value": 12.5 }] });
        let result = execute_set_sheet_cells(&params, &db_state).unwrap();
        let parsed: serde_json::Value = serde_json::from_str(&result).unwrap();
        assert_eq!(parsed["written"], 1, "before fix: a bare JSON decimal silently wrote nothing: {:?}", parsed);

        let data = get_sheet_data_value(&db_state, &note_id);
        let raw = data["cells"][0]["raw_value"].as_str().unwrap().to_string();
        assert_eq!(raw, "12.5", "must be exactly '12.5' — before fix this was '' ; a naive f64 round-trip risks '12.500000000000002'");
        assert!(!raw.contains("000000"), "must not introduce float artifacts: got {}", raw);
    }

