    #[test]
    fn test_set_sheet_cells_object_value_fails_only_that_cell_others_commit() {
        let app = setup();
        let db_state = app.state::<DbState>();
        { let conn = db_state.0.lock().unwrap(); seed_project(&conn, "proj-a", "ProjectA", false); }
        let note_id = create_sheet_for_test(&db_state, "proj-a", "Coerce Sheet");
        let row_result = execute_add_sheet_row(&serde_json::json!({ "note_id": note_id }), &db_state).unwrap();
        let row_id = serde_json::from_str::<serde_json::Value>(&row_result).unwrap()["row_id"].as_str().unwrap().to_string();
        let data = get_sheet_data_value(&db_state, &note_id);
        let col_ids: Vec<String> = data["columns"].as_array().unwrap().iter().take(2).map(|c| c["id"].as_str().unwrap().to_string()).collect();

        let cells = serde_json::json!([
            { "row_id": row_id, "column_id": col_ids[0], "value": { "nested": "oops" } },
            { "row_id": row_id, "column_id": col_ids[1], "value": "Good" },
        ]);
        let params = serde_json::json!({ "note_id": note_id, "cells": cells });
        let result = execute_set_sheet_cells(&params, &db_state).unwrap();
        let parsed: serde_json::Value = serde_json::from_str(&result).unwrap();
        // Before fix: both cells "succeeded" (written: 2, errors: []), the object cell silently blanked.
        assert_eq!(parsed["written"], 1, "only the valid cell must be written: {:?}", parsed);
        let errors = parsed["errors"].as_array().unwrap();
        assert_eq!(errors.len(), 1, "the object value must be rejected as a per-cell error, not silently blanked: {:?}", parsed);
        assert_eq!(errors[0]["row_id"], row_id);
        assert_eq!(errors[0]["column_id"], col_ids[0]);

        let data = get_sheet_data_value(&db_state, &note_id);
        let cells_out = data["cells"].as_array().unwrap();
        assert_eq!(cells_out.len(), 1, "the other cell in the same call must still have committed");
        assert_eq!(cells_out[0]["column_id"], col_ids[1]);
        assert_eq!(cells_out[0]["raw_value"], "Good");
    }

