    #[test]
    #[serial(pane_test_root)]
    fn test_branch_a_ambiguous_name_match_refused_lists_colliding_ids_creates_nothing() {
        let (app, _fs) = setup();
        let db_state = app.state::<DbState>();
        let project = make_project(&db_state, "Branch A Ambiguous");
        let (id1, id2) = {
            let conn = db_state.0.lock().unwrap();
            (
                seed_colliding_sibling(&conn, &project.id, "Budget"),
                seed_colliding_sibling(&conn, &project.id, "budget"),
            )
        };

        let before = note_count(&db_state, &project.id);
        let params = serde_json::json!({ "title": "Nope", "project_id": project.id, "folder_id": "Budget" });
        let result = execute_create_note(&params, &db_state, &None);
        assert!(
            result.is_err(),
            "an ambiguous name match must be refused, never auto-picked"
        );
        let err = result.unwrap_err();
        assert!(
            err.contains(&id1) && err.contains(&id2),
            "the ambiguous-match error must list BOTH colliding folder IDs, got: {}",
            err
        );
        assert!(err.contains("ambiguous"), "got: {}", err);
        let after = note_count(&db_state, &project.id);
        assert_eq!(
            before, after,
            "BEFORE: {} notes. AFTER refused call: {} notes — a refused ambiguous-match call must create NOTHING",
            before, after
        );
        teardown();
    }

    #[test]
    #[serial(pane_test_root)]
    fn test_branch_a_no_match_refused_lists_project_folders_creates_nothing() {
        let (app, _fs) = setup();
        let db_state = app.state::<DbState>();
        let project = make_project(&db_state, "Branch A No Match");
        make_folder(&db_state, &project.id, "Receipts");

        let before = note_count(&db_state, &project.id);
        let params = serde_json::json!({ "title": "Nope", "project_id": project.id, "folder_id": "Nonexistent" });
        let result = execute_create_note(&params, &db_state, &None);
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.contains("not found in this project"));
        assert!(
            err.contains("Receipts"),
            "the no-match error must list the project's real folders, got: {}",
            err
        );
        let after = note_count(&db_state, &project.id);
        assert_eq!(
            before, after,
            "BEFORE: {} notes. AFTER refused call: {} notes — a refused no-match call must create NOTHING",
            before, after
        );
        teardown();
    }

    #[test]
    #[serial(pane_test_root)]
